    void resetView(){if(map==null||getWidth()==0||getHeight()==0)return;base=Math.min(getWidth()/(float)map.getWidth(),getHeight()/(float)map.getHeight());if(base<=0)base=1;zoom=1;N n=find(current);float s=base;tx=getWidth()/2f-(n==null?map.getWidth()/2f:n.x)*s;ty=getHeight()/2f-(n==null?map.getHeight()/2f:n.y)*s;clamp();invalidate();}
    protected void onDraw(Canvas c){super.onDraw(c);if(map==null)return;float s=base*zoom;c.save();c.translate(tx,ty);c.scale(s,s);c.drawBitmap(map,0,0,p);if(showFactions)drawFactions(c);float inv=1/s;for(N n:ns)drawNode(c,n,inv,n==find(current),n.name.equals(selected));c.restore();if(isAttachedToWindow())postInvalidateDelayed(70);}
    void drawFactions(Canvas c){p.setStyle(Paint.Style.FILL);p.setColor(Color.argb(20,92,142,188));Path a=new Path();a.moveTo(22,70);a.lineTo(330,70);a.lineTo(360,470);a.lineTo(180,600);a.lineTo(20,500);a.close();c.drawPath(a,p);p.setColor(Color.argb(20,203,92,65));Path d=new Path();d.moveTo(330,40);d.lineTo(585,40);d.lineTo(580,500);d.lineTo(360,470);d.close();c.drawPath(d,p);p.setColor(Color.argb(20,112,171,95));Path l=new Path();l.moveTo(170,500);l.lineTo(580,480);l.lineTo(570,915);l.lineTo(130,915);l.close();c.drawPath(l,p);}
    void drawNode(Canvas c,N n,float inv,boolean here,boolean sel){int col=dangerColor(n.danger);float r=6*inv;p.setStrokeWidth(2.1f*inv);p.setStyle(Paint.Style.STROKE);p.setColor(col);float x=n.x,y=n.y;if("capital".equals(n.type)){Path q=new Path();q.moveTo(x,y-9*inv);q.lineTo(x+9*inv,y);q.lineTo(x,y+9*inv);q.lineTo(x-9*inv,y);q.close();c.drawPath(q,p);c.drawCircle(x,y,2.4f*inv,p);}else if("fortress".equals(n.type)){c.drawRect(x-7*inv,y-7*inv,x+7*inv,y+7*inv,p);c.drawLine(x-7*inv,y-7*inv,x,y-12*inv,p);c.drawLine(x,y-12*inv,x+7*inv,y-7*inv,p);}else if("dungeon".equals(n.type)){Path q=new Path();q.moveTo(x,y-9*inv);q.lineTo(x+8*inv,y+7*inv);q.lineTo(x-8*inv,y+7*inv);q.close();c.drawPath(q,p);}else if("temple".equals(n.type)){c.drawCircle(x,y,8*inv,p);c.drawCircle(x,y,3*inv,p);}else if("gate".equals(n.type)){c.drawCircle(x,y,8*inv,p);c.drawLine(x,y-8*inv,x,y+8*inv,p);}else if("anomaly".equals(n.type)){c.drawCircle(x,y,8*inv,p);c.drawLine(x-7*inv,y,x+7*inv,y,p);c.drawLine(x,y-7*inv,x,y+7*inv,p);}else c.drawCircle(x,y,r,p);p.setStyle(Paint.Style.FILL);p.setColor(Color.argb(224,3,9,13));p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(dp(7)*inv);float tw=p.measureText(n.name),pad=4*inv,lh=13*inv;float lx=x+11*inv,ly=y-9*inv;if(lx+tw+pad*2>map.getWidth())lx=x-tw-pad*2-11*inv;c.drawRoundRect(lx-pad,ly-lh*.65f,lx+tw+pad,ly+lh*.45f,4*inv,4*inv,p);p.setColor(Color.rgb(235,230,214));c.drawText(n.name,lx,ly,p);if(here){float pulse=(System.currentTimeMillis()%1600)/1600f;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3*inv);p.setColor(Color.argb((int)(210*(1-pulse)),244,204,103));c.drawCircle(x,y,(14+23*pulse)*inv,p);p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(244,204,103));c.drawCircle(x,y,4.5f*inv,p);}if(sel){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2.5f*inv);p.setColor(Color.rgb(92,190,178));c.drawCircle(x,y,15*inv,p);p.setStyle(Paint.Style.FILL);}}
    int dangerColor(int d){return d>=8?Color.rgb(219,86,75):d>=6?Color.rgb(219,145,74):d>=4?Color.rgb(219,187,104):Color.rgb(92,184,174);}
    public boolean onTouchEvent(MotionEvent e){gestures.onTouchEvent(e);scaleDetector.onTouchEvent(e);switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:getParent().requestDisallowInterceptTouchEvent(true);lastX=e.getX();lastY=e.getY();drag=false;return true;case MotionEvent.ACTION_MOVE:if(!scaleDetector.isInProgress()){float dx=e.getX()-lastX,dy=e.getY()-lastY;if(Math.abs(dx)+Math.abs(dy)>6)drag=true;tx+=dx;ty+=dy;lastX=e.getX();lastY=e.getY();clamp();invalidate();}return true;case MotionEvent.ACTION_UP:if(!drag)select(e.getX(),e.getY());getParent().requestDisallowInterceptTouchEvent(false);return true;case MotionEvent.ACTION_CANCEL:getParent().requestDisallowInterceptTouchEvent(false);return true;}return true;}
    void select(float sx,float sy){float s=base*zoom,mx=(sx-tx)/s,my=(sy-ty)/s;N best=null;float bd=Float.MAX_VALUE;for(N n:ns){float dx=n.x-mx,dy=n.y-my,d=dx*dx+dy*dy;if(d<bd){bd=d;best=n;}}if(best!=null&&bd<62*62){selected=best.name;performClick();invalidate();if(listener!=null)listener.onLocationSelected(best.name,best.danger);}}
