    void emblem(Canvas c,int i,float x,float y){if(i==0){Path q=new Path();for(int k=0;k<8;k++){double a=-Math.PI/2+k*Math.PI/4;float rr=dp(k%2==0?14:6);float px=x+(float)Math.cos(a)*rr,py=y+(float)Math.sin(a)*rr;if(k==0)q.moveTo(px,py);else q.lineTo(px,py);}q.close();c.drawPath(q,p);c.drawCircle(x,y,dp(3),p);}else if(i==1){Path q=new Path();q.moveTo(x,y-dp(15));q.lineTo(x+dp(10),y-dp(4));q.lineTo(x+dp(5),y+dp(15));q.lineTo(x,y+dp(7));q.lineTo(x-dp(6),y+dp(15));q.lineTo(x-dp(11),y-dp(4));q.close();c.drawPath(q,p);c.drawLine(x,y-dp(10),x,y+dp(9),p);}else{Path q=new Path();q.moveTo(x,y-dp(15));q.cubicTo(x+dp(17),y-dp(8),x+dp(14),y+dp(12),x,y+dp(15));q.cubicTo(x-dp(14),y+dp(12),x-dp(17),y-dp(8),x,y-dp(15));c.drawPath(q,p);c.drawLine(x,y-dp(10),x,y+dp(12),p);}}
